import{_ as o,C as t,o as r,c as s,E as a,a2 as l}from"./chunks/framework.Cm6XCzck.js";const d="/joinwell52/assets/figures/miit-414/en/01-service-lifecycle.png",c="/joinwell52/assets/figures/miit-414/en/02-action-timeline.png",p="/joinwell52/assets/figures/miit-414/en/03-policy-mechanism.png",h="/joinwell52/assets/figures/miit-414/en/04-five-annexes.png",k=JSON.parse('{"title":"MIIT Document No. 414 Explained: From Model Supply to Application Delivery","description":"","frontmatter":{"title":"MIIT Document No. 414 Explained: From Model Supply to Application Delivery","date":"2026-09-04","language":"en","article_type":"policy-analysis","summary":"MIIT Document No. 414 uses provider pools, service consortia, real-world scenarios, and ongoing evaluation to build scalable AI application delivery capacity. This article examines the policy mechanism, participation requirements, and opportunities in application delivery.","publication_authorized":true,"lifecycle":"Published","column":"industry-architecture","category":"daily","edition":"research-center","cover":"/assets/covers/miit-414-policy-cover.png"},"headers":[],"relativePath":"en/industry/2026-09-04-miit-414-ai-application-delivery.md","filePath":"en/industry/2026-09-04-miit-414-ai-application-delivery.md","lastUpdated":1788533514000}'),u={name:"en/industry/2026-09-04-miit-414-ai-application-delivery.md"};function m(g,e,f,y,v,b){const i=t("ArticleCover"),n=t("ArticleTableScroll");return r(),s("div",null,[a(i,{image:"/assets/covers/miit-414-policy-cover.png",kicker:"Industry Architecture · Policy Analysis",title:"MIIT Document No. 414 Explained: From Model Supply to Application Delivery",summary:"MIIT Document No. 414 uses provider pools, service consortia, real-world scenarios, and ongoing evaluation to build scalable AI application delivery capacity. This article examines the policy mechanism, participation requirements, and opportunities in application delivery.",version:"2026-09-04",languageHref:"/zh/industry/2026-09-04-miit-414-ai-application-delivery",languageLabel:"中文版"}),a(n,{language:"en",class:"miit-414-tables"}),e[0]||(e[0]=l('<h1 id="miit-document-no-414-explained-from-model-supply-to-application-delivery" tabindex="-1">MIIT Document No. 414 Explained: From Model Supply to Application Delivery <a class="header-anchor" href="#miit-document-no-414-explained-from-model-supply-to-application-delivery" aria-label="Permalink to &quot;MIIT Document No. 414 Explained: From Model Supply to Application Delivery&quot;">​</a></h1><h2 id="a-new-ai-application-service-industry-is-being-formally-established" tabindex="-1">A new AI application service industry is being formally established <a class="header-anchor" href="#a-new-ai-application-service-industry-is-being-formally-established" aria-label="Permalink to &quot;A new AI application service industry is being formally established&quot;">​</a></h2><p>On August 31, 2026, China&#39;s Ministry of Industry and Information Technology (MIIT) published the Notice on Launching a Special Action to Foster Artificial Intelligence Application Service Providers, numbered Gong Xin Ting Ke Han [2026] No. 414. The document was dated August 27 and addressed to the industry and information technology authorities of all provinces, autonomous regions, municipalities directly under the central government, and the Xinjiang Production and Construction Corps.</p><p>A news headline alone could make this look like another general statement supporting AI. Reading the notice, its five annexes, and the subsequent explanation from MIIT&#39;s Department of Science and Technology reveals a more specific problem. The question is no longer simply whether China has large models or enough computing power. It is this: <strong>who can connect models, data, computing resources, and agents to real enterprises, keep them operating, and take responsibility for effectiveness, security, and compliance?</strong></p><p>Document No. 414 gives this previously indistinct industrial role a formal name: <strong>AI application service provider</strong>.</p><p>It also goes beyond naming the category. It sets out local surveys, provider profiles, a national resource pool, service consortia, real-world scenarios, first-purchase and first-use mechanisms, risk compensation, computing vouchers, talent development, standards, dynamic updates, and implementation evaluation. In other words, it seeks to build infrastructure for a market, rather than merely attach a new label to it.</p><p>The central argument of this article is that <strong>China&#39;s AI policy is moving beyond the creation of model and computing supply toward the development of scalable application delivery capacity. Document No. 414 is not the beginning of that shift, but it is an important marker of AI application service providers being systematically organized as a distinct policy subject.</strong></p><p>The notice and its five annexes are available on the <a href="https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_331b6f1d28ad410aa9df711acf42dbfe.html" target="_blank" rel="noreferrer">official MIIT publication page</a>.</p><h2 id="why-now-technical-supply-has-grown-faster-than-delivery-capacity" tabindex="-1">Why now: technical supply has grown faster than delivery capacity <a class="header-anchor" href="#why-now-technical-supply-has-grown-faster-than-delivery-capacity" aria-label="Permalink to &quot;Why now: technical supply has grown faster than delivery capacity&quot;">​</a></h2><p>Several published figures help explain the context.</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Published figures</th><th>What they suggest</th></tr></thead><tbody><tr><td>China&#39;s core AI industry</td><td>More than RMB 1.2 trillion in 2025, with over 6,200 enterprises</td><td>Technical supply has reached substantial scale</td></tr><tr><td>Average daily token usage in China</td><td>Approximately 100 billion in early 2024, about 100 trillion at the end of 2025, and over 140 trillion in March 2026</td><td>Models are moving from training and demonstrations to large-scale use</td></tr><tr><td>AI adoption among manufacturing enterprises above the designated size</td><td>Over 30% in the first half of 2026</td><td>AI has entered production, but most enterprises remain outside this measure of adoption</td></tr><tr><td>Global organizational AI use</td><td>78% in 2024, compared with 55% in 2023</td><td>Adoption is growing quickly, but use does not automatically create stable value</td></tr><tr><td>China&#39;s SME digital transformation pilots</td><td>Two rounds covering 66 cities and supporting over 30,000 enterprises; policy targets of around 100 cities and more than 40,000 enterprises</td><td>Government already has experience organizing enterprise transformation through cities and service providers</td></tr></tbody></table><p>The RMB 1.2 trillion and 6,200-enterprise figures were disclosed by the MIIT minister during the ministerial interview session at the 2026 Two Sessions. Growth in average daily token usage from 100 billion to 140 trillion represents an increase of more than 1,000-fold in roughly two years, with about 40% growth between the end of 2025 and March 2026. <a href="https://data.beijing.gov.cn/xydt/ljhd/3ec621d485334da1acb48eb907172bdd.htm" target="_blank" rel="noreferrer">Public information attributed to the National Data Administration</a> connects this trend with AI moving from conversation toward decision-making and execution. The manufacturing adoption figure of over 30% in the first half of 2026 further indicates that applications are entering the real economy. <a href="https://gxt.hunan.gov.cn/xxgk_71033/gzdt/rdjj/202608/t20260824_34049455.html" target="_blank" rel="noreferrer">Related industrial figures</a></p><p>These increases also expose a structural gap. Models are improving, token usage is expanding, and enterprises are willing to experiment, yet many projects remain pilots, demonstrations, or isolated tools. Production introduces a different set of questions: how to connect existing systems, whether business data can be used, who holds invocation permissions, how execution errors are recovered, whether the application survives a model replacement, how outcomes are accepted, who is accountable for security incidents, and who maintains the system after launch.</p><p>International data reflects a similar tension. Stanford&#39;s 2025 AI Index reports that 78% of organizations used AI in 2024, up from 55% in 2023. Widespread adoption, however, has not automatically resolved governance, reliability, or value realization. <a href="https://hai.stanford.edu/ai-index/2025-ai-index-report" target="_blank" rel="noreferrer">Stanford AI Index 2025</a></p><p>The bottleneck is therefore no longer only whether a model can perform a task. It is whether an organization can use it reliably. Document No. 414 addresses that distance between technical capability and productive capability.</p><h2 id="what-the-title-means-a-special-action-to-foster-providers" tabindex="-1">What the title means: a special action to foster providers <a class="header-anchor" href="#what-the-title-means-a-special-action-to-foster-providers" aria-label="Permalink to &quot;What the title means: a special action to foster providers&quot;">​</a></h2><p>The title of the policy already establishes its character.</p><p>“Foster” indicates that the government sees an emerging market whose participants, capability expectations, and commercial practices are not yet well defined. It is not creating an industry from nothing or directly selecting a few favored companies. Identification, profiling, classification, support, and evaluation are intended to turn dispersed participants into a recognizable industrial community.</p><p>“Special” narrows the focus to a particular bottleneck: insufficient application delivery services, rather than AI development in general.</p><p>“Action” denotes an implementation program with targets, a timetable, responsible bodies, and evaluation. It is not an administrative regulation establishing a permanent system of rights and obligations. Its milestones include December 1, 2026, the end of 2026, December 1, 2027, and the end of 2027.</p><p>Document No. 414 is therefore not an “AI application service provider license,” nor does it state that providers outside the pool may not operate. It is better understood as an industrial organization initiative: central authorities set the direction, local authorities implement it, enterprises and institutions participate, and standards and resources follow.</p><h2 id="the-recipients-reveal-who-will-implement-it" tabindex="-1">The recipients reveal who will implement it <a class="header-anchor" href="#the-recipients-reveal-who-will-implement-it" aria-label="Permalink to &quot;The recipients reveal who will implement it&quot;">​</a></h2><p>The notice is addressed to provincial-level industry and information technology authorities, including the relevant authority of the Xinjiang Production and Construction Corps, rather than directly to enterprises. This matters.</p><p>A company does not complete entry into the pool simply by sending an application to MIIT. Regions first identify providers, consolidate information, establish local pools, and report to MIIT&#39;s Department of Science and Technology. Central authorities form the national pool, develop standards, and conduct overall evaluation. Local authorities identify enterprises, organize consortia, and connect local scenarios with policy resources.</p><p>This is a central-framework, local-implementation approach. Whether a company catches the first window may depend less on whether it has read the central notice than on whether it becomes visible to its provincial or municipal industrial authority, industrial park, industry association, or relevant solicitation channel.</p><p>Is this government-driven? <strong>Yes. But the government is not developing AI for enterprises itself. It is organizing directories, standards, scenarios, procurement, risk sharing, public resources, and evaluation to reduce the cost and risk of initial cooperation between buyers and providers.</strong></p><h2 id="the-opening-definition-redraws-the-ai-value-chain" tabindex="-1">The opening definition redraws the AI value chain <a class="header-anchor" href="#the-opening-definition-redraws-the-ai-value-chain" aria-label="Permalink to &quot;The opening definition redraws the AI value chain&quot;">​</a></h2><p>The document defines AI application service providers as enterprises or institutions that address the intelligent transformation needs of user organizations through services such as solution consulting and planning, delivery and implementation, operations management, and security governance. Each part of this definition matters.</p><h3 id="starting-from-organizational-needs" tabindex="-1">Starting from organizational needs <a class="header-anchor" href="#starting-from-organizational-needs" aria-label="Permalink to &quot;Starting from organizational needs&quot;">​</a></h3><p>The definition does not begin with model parameters, algorithmic choices, or computing scale. It starts with customer needs. A provider&#39;s value depends on its ability to identify and solve customer problems, not on the size of a model it owns.</p><p>The reference to “user organizations,” rather than individual consumers, also places the initial emphasis on institutional markets: enterprises, public institutions, and other organizations with business processes. Providers must understand procurement, deployment, permissions, workflows, responsibility, acceptance, and continuing operations. A personal chat interface is not enough.</p><h3 id="consulting-delivery-operations-and-governance-cover-the-full-lifecycle" tabindex="-1">Consulting, delivery, operations, and governance cover the full lifecycle <a class="header-anchor" href="#consulting-delivery-operations-and-governance-cover-the-full-lifecycle" aria-label="Permalink to &quot;Consulting, delivery, operations, and governance cover the full lifecycle&quot;">​</a></h3><p>These services form a lifecycle: determine why and where AI should be used, build the system, keep it running, and embed security and compliance throughout.</p><p>Traditional software outsourcing often treats launch as the delivery endpoint. Generative AI introduces probabilistic outputs, changing models, complex tool permissions, and variable operating costs. An agent that passes a test today may not remain reliable tomorrow. A task marked “finished” may not have produced a correctly accepted business result. Including operations and security governance in the definition makes them part of the service itself, rather than optional after-sales support.</p><h3 id="enterprises-and-institutions-participation-is-not-reserved-for-large-technology-companies" tabindex="-1">Enterprises and institutions: participation is not reserved for large technology companies <a class="header-anchor" href="#enterprises-and-institutions-participation-is-not-reserved-for-large-technology-companies" aria-label="Permalink to &quot;Enterprises and institutions: participation is not reserved for large technology companies&quot;">​</a></h3><p>Annex 1 allows reporting by state-owned, private, foreign-invested, and joint-venture enterprises, public institutions, social organizations, universities, research institutions, and other organization types. Annex 3 further requires a legal person or unincorporated organization registered and operating normally within the People&#39;s Republic of China.</p><p>Individual developers therefore cannot enter the pool solely in a personal capacity, and overseas companies cannot report solely through an offshore entity. Universities, research institutes, social organizations, and smaller local service businesses may nevertheless participate. The pool is designed to create multiple layers of service supply, rather than select only national champions.</p><p><a href="/joinwell52/assets/figures/miit-414/en/01-service-lifecycle.png"><img src="'+d+'" alt="The full AI application service lifecycle"></a></p><p><em>Figure 1. The full AI application service lifecycle. Select the image to view it at full size.</em></p><h2 id="eight-phrases-in-the-objectives-describe-the-intended-market" tabindex="-1">Eight phrases in the objectives describe the intended market <a class="header-anchor" href="#eight-phrases-in-the-objectives-describe-the-intended-market" aria-label="Permalink to &quot;Eight phrases in the objectives describe the intended market&quot;">​</a></h2><h3 id="use-the-special-action-as-a-driving-force" tabindex="-1">“Use the special action as a driving force” <a class="header-anchor" href="#use-the-special-action-as-a-driving-force" aria-label="Permalink to &quot;“Use the special action as a driving force”&quot;">​</a></h3><p>The government intends to organize dispersed supply through policy signals and public resources, rather than take over the market. Enterprises must still build products, deliver services, and establish viable businesses.</p><h3 id="establish-a-provider-resource-pool" tabindex="-1">“Establish a provider resource pool” <a class="header-anchor" href="#establish-a-provider-resource-pool" aria-label="Permalink to &quot;“Establish a provider resource pool”&quot;">​</a></h3><p>The pool serves several functions: market mapping, participant classification, capability presentation, supplier discovery, and subsequent policy outreach. MIIT also proposes an online platform at an appropriate time, suggesting that the pool may develop into a national service capability directory.</p><h3 id="targeted-improvement" tabindex="-1">“Targeted improvement” <a class="header-anchor" href="#targeted-improvement" aria-label="Permalink to &quot;“Targeted improvement”&quot;">​</a></h3><p>Support is intended to address specific capability gaps rather than be distributed uniformly. Pilot-scale testing bases, incubators, computing vouchers, API trials, practical training facilities, and expert guidance are among the possible tools.</p><h3 id="technological-innovation-integrated-delivery-and-security-compliance" tabindex="-1">“Technological innovation, integrated delivery, and security compliance” <a class="header-anchor" href="#technological-innovation-integrated-delivery-and-security-compliance" aria-label="Permalink to &quot;“Technological innovation, integrated delivery, and security compliance”&quot;">​</a></h3><p>Placing these three capabilities together moves evaluation beyond technical competence alone. Developing a system does not prove that a company can integrate it, and integration does not prove safe operation. Complex business scenarios require all three.</p><h3 id="understand-industry-pain-points-technical-mechanisms-security-risks-and-delivery-operations" tabindex="-1">“Understand industry pain points, technical mechanisms, security risks, and delivery operations” <a class="header-anchor" href="#understand-industry-pain-points-technical-mechanisms-security-risks-and-delivery-operations" aria-label="Permalink to &quot;“Understand industry pain points, technical mechanisms, security risks, and delivery operations”&quot;">​</a></h3><p>These capabilities span business knowledge, technology, governance, and implementation. Training a large model is not listed as a universal prerequisite. The scarce resource is a multidisciplinary team that can work across business and technical boundaries.</p><h3 id="a-reasonable-structure-orderly-division-of-labor-and-collaborative-innovation" tabindex="-1">“A reasonable structure, orderly division of labor, and collaborative innovation” <a class="header-anchor" href="#a-reasonable-structure-orderly-division-of-labor-and-collaborative-innovation" aria-label="Permalink to &quot;“A reasonable structure, orderly division of labor, and collaborative innovation”&quot;">​</a></h3><p>The aim is not to have 3,000 companies offer identical services. Model, computing, data, terminal, integration, operations, security, and evaluation providers can occupy different positions and combine through service consortia.</p><h3 id="multiple-tiers" tabindex="-1">“Multiple tiers” <a class="header-anchor" href="#multiple-tiers" aria-label="Permalink to &quot;“Multiple tiers”&quot;">​</a></h3><p>This leaves room for national leaders, regional providers, industry specialists, and small professional institutions. The absence of a universal minimum registered capital or revenue threshold in the annexes is consistent with that approach.</p><h3 id="delivery-capability-for-complex-scenarios" tabindex="-1">“Delivery capability for complex scenarios” <a class="header-anchor" href="#delivery-capability-for-complex-scenarios" aria-label="Permalink to &quot;“Delivery capability for complex scenarios”&quot;">​</a></h3><p>Complex delivery is an objective, not the universal entry requirement. The policy supports small, rapid, lightweight, and precisely targeted products while also raising the ceiling for larger projects through consortia, hardware and software compatibility, and multi-model coordination. These are parallel routes.</p><h2 id="the-2-000-and-3-000-targets-are-about-more-than-headcount" tabindex="-1">The 2,000 and 3,000 targets are about more than headcount <a class="header-anchor" href="#the-2-000-and-3-000-targets-are-about-more-than-headcount" aria-label="Permalink to &quot;The 2,000 and 3,000 targets are about more than headcount&quot;">​</a></h2><p>Document No. 414 targets a national resource pool of more than 2,000 providers by the end of 2026 and no fewer than 3,000 by the end of 2027. Provinces containing national AI industry innovation and application pilot zones should have at least 100 providers in their local pools by the end of 2027.</p><p>These are organizational targets, not revenue targets. They show an intention to conduct a first systematic inventory of national service supply within a short period, with enough regional and sectoral density for enterprises to find delivery teams.</p><p>Pool expansion also means competition will remain substantial. A pool of 2,000–3,000 providers does not automatically create scarcity, and membership alone is unlikely to become a durable competitive advantage. Differentiation will depend on industry cases, repeat purchases, delivery costs, reliability, security capabilities, and reusable products.</p><p><a href="/joinwell52/assets/figures/miit-414/en/02-action-timeline.png"><img src="'+c+'" alt="Action deadlines and resource pool targets"></a></p><p><em>Figure 2. Action deadlines and resource pool targets. Select the image to view it at full size.</em></p><h2 id="four-tasks-form-an-industrial-organization-mechanism" tabindex="-1">Four tasks form an industrial organization mechanism <a class="header-anchor" href="#four-tasks-form-an-industrial-organization-mechanism" aria-label="Permalink to &quot;Four tasks form an industrial organization mechanism&quot;">​</a></h2><h3 id="task-1-identify-providers-and-make-supply-discoverable" tabindex="-1">Task 1: identify providers and make supply discoverable <a class="header-anchor" href="#task-1-identify-providers-and-make-supply-discoverable" aria-label="Permalink to &quot;Task 1: identify providers and make supply discoverable&quot;">​</a></h3><p>Local authorities must establish provider profiles and local resource pools. MIIT will then form and publish a national pool, at an appropriate time, using relevant standards.</p><p>This addresses a basic policy problem. Without knowing which providers exist, which sectors they serve, and what they have delivered, authorities cannot match supply with demand or target support. The pool is a form of supply-side information infrastructure.</p><p>The reference to relevant standards also means local reporting does not necessarily guarantee admission to the national pool. MIIT&#39;s explanatory material says that general provider requirements, maturity assessment standards, and graded capability requirements for forward-deployed engineers are being developed. <a href="https://www.ordoszxqy.org.cn/policy/info/6015" target="_blank" rel="noreferrer">Reprint of the Department of Science and Technology&#39;s explanation</a></p><p>The first stage may emphasize profiling and coverage; standardization, differentiated levels, and dynamic removal may follow.</p><h3 id="task-2-move-from-individual-companies-to-integrated-delivery-with-shared-participation" tabindex="-1">Task 2: move from individual companies to integrated delivery with shared participation <a class="header-anchor" href="#task-2-move-from-individual-companies-to-integrated-delivery-with-shared-participation" aria-label="Permalink to &quot;Task 2: move from individual companies to integrated delivery with shared participation&quot;">​</a></h3><p>The second task introduces AI application service consortia, including model–data coordination and computing–power coordination. Real AI projects rarely depend on one enterprise alone: models require data; inference requires computing and electricity; software depends on operating systems and databases; applications also require terminals, integration, and security governance.</p><p>Each consortium has one lead service provider and at least two upstream or downstream participants. The lead role matters because complex projects still need an entity accountable for the overall solution and customer delivery. Collaboration must not dissolve responsibility.</p><p>The document also addresses hardware and software compatibility, multi-model coordination, and the integration of secure and reliable operating systems, databases, and AI training and inference chips. This should not simply be rewritten as “mandatory domestic sourcing”: the notice uses encouragement and security/reliability language without specifying particular brands or origins. It does, however, suggest that solutions relying on one overseas model, one cloud platform, or one development environment may struggle to serve the full range of public-sector and important industrial scenarios. Replaceability, adaptability, and portability will be important engineering capabilities.</p><h3 id="task-3-organize-demand-as-well-as-supply" tabindex="-1">Task 3: organize demand as well as supply <a class="header-anchor" href="#task-3-organize-demand-as-well-as-supply" aria-label="Permalink to &quot;Task 3: organize demand as well as supply&quot;">​</a></h3><p>The third task is closest to the sources of commercial opportunity. It promotes modular, standardized product packages for frequent, essential, reusable business needs; supply–demand matching through alliances, associations, and open-source communities; access to real scenarios; and exploration of first-purchase, first-use, risk-compensation, and procurement mechanisms for large models, agents, and token services.</p><p>The approach addresses three familiar barriers:</p><ul><li>Customers do not know what to buy, creating a need for standardized products and industry matching.</li><li>Customers hesitate to be the first to bear failure risk, creating a role for first-use and risk-sharing mechanisms.</li><li>Providers lack real data and scenarios, making it difficult to accumulate cases, so public and industrial scenarios need to become accessible.</li></ul><p>Calls for increased procurement suggest that government and relevant institutions may organize early demand. But the word “explore” means that amounts, subsidy ratios, and scope depend on later local policies and projects. Enterprises cannot book a policy direction as certain revenue.</p><h3 id="task-4-provide-shared-support-through-computing-tools-data-and-talent" tabindex="-1">Task 4: provide shared support through computing, tools, data, and talent <a class="header-anchor" href="#task-4-provide-shared-support-through-computing-tools-data-and-talent" aria-label="Permalink to &quot;Task 4: provide shared support through computing, tools, data, and talent&quot;">​</a></h3><p>The fourth task covers national computing nodes, the China computing platform, computing vouchers, intelligent coding tools, open interfaces, trials, practical training facilities, and forward-deployed engineer (FDE) teams. The aim is to reduce providers&#39; access costs for essential inputs.</p><p>The proposal to improve intelligent coding tools and expand software supply is particularly significant. Coding assistance is treated as a means of increasing application software supply and shortening delivery cycles, rather than only improving individual programmer productivity.</p><p>FDEs represent a developing delivery role. They are neither purely coding-focused R&amp;D engineers nor relationship-focused presales staff. They work close to users to understand business needs, combine models and systems, solve deployment problems, and maintain application effectiveness. Their inclusion recognizes the last mile as a problem requiring a dedicated talent system.</p><p><a href="/joinwell52/assets/figures/miit-414/en/03-policy-mechanism.png"><img src="'+p+'" alt="How the four policy tasks fit together"></a></p><p><em>Figure 3. How the four policy tasks fit together. Select the image to view it at full size.</em></p><h2 id="the-five-annexes-make-participation-requirements-concrete" tabindex="-1">The five annexes make participation requirements concrete <a class="header-anchor" href="#the-five-annexes-make-participation-requirements-concrete" aria-label="Permalink to &quot;The five annexes make participation requirements concrete&quot;">​</a></h2><p>The main text sets the direction. The annexes determine how providers are identified, what evidence supports their claims, and how the action is evaluated.</p><h3 id="annex-1-provider-profiles-record-operating-and-delivery-facts" tabindex="-1">Annex 1: provider profiles record operating and delivery facts <a class="header-anchor" href="#annex-1-provider-profiles-record-operating-and-delivery-facts" aria-label="Permalink to &quot;Annex 1: provider profiles record operating and delivery facts&quot;">​</a></h3><p>The profile collects registration details, organization type, establishment date, years in AI services, annual revenue, AI service revenue, total staff, AI service team size, organizational structure, staff qualifications, served industries, service categories, and actual cases.</p><p>Five implications follow.</p><p>First, separately reporting AI service revenue helps distinguish businesses genuinely providing AI services from those that have merely adopted the label.</p><p>Second, teams must explain organization, capabilities, and responsibilities, with social insurance evidence for staff. This discourages temporary assembly of nominal external personnel.</p><p>Third, providers identifying specific sectors may select up to three principal industries, although an all-industry option also exists. The structure favors a verifiable industry position over an undifferentiated general pitch.</p><p>Fourth, cases must identify customers, contract amounts, implementation periods, scenarios, solutions, and results, supported by contracts or evidence of application. Repositories, demonstrations, papers, patents, and media coverage can establish that technology exists; they do not replace actual service cases.</p><p>Fifth, providers make commitments concerning truthful materials, tax and credit standing, the absence of major financial violations or debt defaults in the previous three years, intellectual property, lawful activity, and the non-confidential, publishable nature of submitted material. Participation therefore involves public disclosure and credit responsibility as well as capability.</p><h3 id="annex-2-the-pool-template-acts-as-a-service-capability-index" tabindex="-1">Annex 2: the pool template acts as a service capability index <a class="header-anchor" href="#annex-2-the-pool-template-acts-as-a-service-capability-index" aria-label="Permalink to &quot;Annex 2: the pool template acts as a service capability index&quot;">​</a></h3><p>The pool table retains concise structured fields such as provider name, service category, principal industries, main customer types, and contact details. It is an index for finding providers, rather than the full assessment record.</p><p>An eventual online platform may therefore initially function as a discovery tool. Providers that can explain whom they serve, what they solve, and what they have delivered in a few fields are more likely to receive an initial inquiry. Clear industry positioning and customer evidence matter more than a long list of technical terms.</p><h3 id="annex-3-reporting-requirements-emphasize-real-delivery-rather-than-company-size" tabindex="-1">Annex 3: reporting requirements emphasize real delivery rather than company size <a class="header-anchor" href="#annex-3-reporting-requirements-emphasize-real-delivery-rather-than-company-size" aria-label="Permalink to &quot;Annex 3: reporting requirements emphasize real delivery rather than company size&quot;">​</a></h3><p>Annex 3 sets out the most explicit current reporting conditions:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Stated requirement</th><th>Implication</th></tr></thead><tbody><tr><td>Entity</td><td>Registered and operating normally in China, with principal business covering AI-related services</td><td>Excludes personal projects and purely conceptual entities</td></tr><tr><td>Credit</td><td>No serious credit or legal violations by the enterprise, legal representative, or actual controller in the previous three years</td><td>Responsibility extends to key individuals</td></tr><tr><td>Intellectual property</td><td>No infringement of third-party intellectual property</td><td>Models, data, code, and content provenance matter to delivery risk</td></tr><tr><td>Team</td><td>In principle, at least three direct service staff, with social insurance evidence</td><td>Small teams can participate, but must be real and stable</td></tr><tr><td>Basic conditions</td><td>Necessary premises, equipment, and tools</td><td>Capability must be deliverable through an organization</td></tr><tr><td>Process</td><td>Complete, usable, standardized service manuals or documentation</td><td>Ad hoc performance is not a substitute for service capability</td></tr><tr><td>Cases</td><td>For providers with under three years of experience, in principle at least 10 cases; for those with three or more years, at least 30 cases in the past three years</td><td>Actual delivery records are a substantive threshold</td></tr></tbody></table><p>The annexes collect registered capital and revenue but do not specify universal minimums for capital, total revenue, or AI revenue. Nor do they make proprietary large models, patent counts, financing scale, or R&amp;D staff degrees universal prerequisites. This creates room for small specialist providers.</p><p>The case threshold is nevertheless meaningful. Newer teams still need, in principle, at least 10 service cases; established providers need at least 30 within three years. The policy favors smaller teams with actual delivery over treating technology demonstrations as equivalent to service provision.</p><h3 id="qualifications-are-triggered-by-the-service-being-offered" tabindex="-1">Qualifications are triggered by the service being offered <a class="header-anchor" href="#qualifications-are-triggered-by-the-service-being-offered" aria-label="Permalink to &quot;Qualifications are triggered by the service being offered&quot;">​</a></h3><p>Third-party testing and evaluation require applicable capability evidence such as CMA/CNAS credentials. Public-facing websites, apps, and mini-programs require applicable filings or permissions. Generative AI services with public-opinion attributes or social-mobilization capabilities require the corresponding filing or registration.</p><p>This is a service-dependent compliance approach, rather than a demand that every provider hold every qualification. Companies should first define their service boundaries and then assemble the appropriate evidence, rather than collect certificates indiscriminately.</p><h3 id="annex-4-service-consortium-information-identifies-a-lead-organization" tabindex="-1">Annex 4: service consortium information identifies a lead organization <a class="header-anchor" href="#annex-4-service-consortium-information-identifies-a-lead-organization" aria-label="Permalink to &quot;Annex 4: service consortium information identifies a lead organization&quot;">​</a></h3><p>Consortia report their lead organization, members, principal industries, combined capabilities, and completed cases. Each consortium should in principle include at least two member organizations, potentially from computing, data, terminals, and other upstream or downstream fields.</p><p>Using 31 provincial-level jurisdictions plus the Xinjiang Production and Construction Corps as a rough basis, a reporting expectation of at least 10 consortia per region suggests around 320 initial consortium submissions nationwide. The same entity may participate in multiple consortia, so this is neither 320 wholly separate sets of companies nor a fixed final total. It nevertheless indicates an attempt to organize a nationwide collaboration network.</p><p>Two opportunities follow. Companies with industry customers and delivery capability can seek a lead role. Specialists in models, data, security, computing, terminals, or operating platforms can enter project delivery as members.</p><h3 id="annex-5-the-summary-assesses-local-implementation-not-just-enterprises" tabindex="-1">Annex 5: the summary assesses local implementation, not just enterprises <a class="header-anchor" href="#annex-5-the-summary-assesses-local-implementation-not-just-enterprises" aria-label="Permalink to &quot;Annex 5: the summary assesses local implementation, not just enterprises&quot;">​</a></h3><p>The final report requires the provincial industrial authority&#39;s seal and covers target achievement, economic and social benefits, contributions to industrial development and new industrialization, implementation measures, lessons, problems, and recommendations.</p><p>The pool is therefore intended to be more than a static list left to enterprise self-promotion. Local authorities must demonstrate what they did and what resulted. MIIT also plans ongoing evaluation, expert field guidance, and identification of exemplary outcomes.</p><p>The responsibility chain is observable: central tasks, local pools and consortia, enterprise delivery, expert follow-up, local summaries, and central evaluation, with results informing subsequent support and projects.</p><p><a href="/joinwell52/assets/figures/miit-414/en/04-five-annexes.png"><img src="'+h+'" alt="The roles of the five annexes"></a></p><p><em>Figure 4. The roles of the five annexes. Select the image to view it at full size.</em></p><h2 id="policy-verbs-have-different-force" tabindex="-1">Policy verbs have different force <a class="header-anchor" href="#policy-verbs-have-different-force" aria-label="Permalink to &quot;Policy verbs have different force&quot;">​</a></h2><p>Reading policy requires distinguishing required actions from potential support.</p><table tabindex="0"><thead><tr><th>Wording</th><th>Broad policy force</th><th>How to read it</th></tr></thead><tbody><tr><td>“Should” or “submit before a specified date”</td><td>A stated task or condition</td><td>Useful for identifying responsibilities and deadlines</td></tr><tr><td>“Will establish” or “will organize”</td><td>A departmental arrangement</td><td>Timing and implementation still need to be followed</td></tr><tr><td>“In principle”</td><td>A qualified threshold or quantity</td><td>The normal expectation, with room for justified exceptions</td></tr><tr><td>“Support” or “guide”</td><td>Policy direction</td><td>Does not automatically entitle every company to resources</td></tr><tr><td>“Encourage”</td><td>An advocated approach</td><td>Implementation depends on local authorities and participants</td></tr><tr><td>“Explore”</td><td>A prospective or pilot mechanism</td><td>First-use and risk-compensation tools are not uniform national entitlements</td></tr><tr><td>“At an appropriate time”</td><td>A direction without a fixed date</td><td>The national pool&#39;s online platform is an example</td></tr></tbody></table><p>The document launches a nationwide organizational action, but does not set uniform subsidy amounts, government procurement quotas, a national pool scoring system, or maturity grades. Opportunity is emerging; revenue still depends on local implementation and enterprise delivery.</p><h2 id="ten-potential-sources-of-opportunity" tabindex="-1">Ten potential sources of opportunity <a class="header-anchor" href="#ten-potential-sources-of-opportunity" aria-label="Permalink to &quot;Ten potential sources of opportunity&quot;">​</a></h2><h3 id="_1-provider-profiling-and-capability-assessment" tabindex="-1">1. Provider profiling and capability assessment <a class="header-anchor" href="#_1-provider-profiling-and-capability-assessment" aria-label="Permalink to &quot;1. Provider profiling and capability assessment&quot;">​</a></h3><p>Software firms, systems integrators, and industry consultants will need to establish whether they fit the provider category and address gaps in teams, processes, cases, and qualifications. Application preparation, maturity diagnostics, and service-system development may create professional demand.</p><h3 id="_2-small-rapid-lightweight-precisely-targeted-product-packages" tabindex="-1">2. Small, rapid, lightweight, precisely targeted product packages <a class="header-anchor" href="#_2-small-rapid-lightweight-precisely-targeted-product-packages" aria-label="Permalink to &quot;2. Small, rapid, lightweight, precisely targeted product packages&quot;">​</a></h3><p>The immediate product opportunity is to package frequent, essential, reusable tasks into offerings that can be installed quickly, priced clearly, and accepted within a short cycle. Examples include R&amp;D document organization, equipment maintenance analysis, supply-chain exception handling, enterprise knowledge queries, compliance checks, customer service, and business reports.</p><h3 id="_3-industry-ai-consulting-and-implementation" tabindex="-1">3. Industry AI consulting and implementation <a class="header-anchor" href="#_3-industry-ai-consulting-and-implementation" aria-label="Permalink to &quot;3. Industry AI consulting and implementation&quot;">​</a></h3><p>The annexes allow providers to highlight up to three principal industries. Teams that understand manufacturing, energy, finance, healthcare, education, or legal-service constraints may be better positioned than developers who know only generic model invocation.</p><h3 id="_4-systems-integration-and-multi-model-adaptation" tabindex="-1">4. Systems integration and multi-model adaptation <a class="header-anchor" href="#_4-systems-integration-and-multi-model-adaptation" aria-label="Permalink to &quot;4. Systems integration and multi-model adaptation&quot;">​</a></h3><p>Enterprises will not abandon ERP, MES, CRM, office systems, or databases for AI. Connecting agents to these business systems and sources of record while supporting model replacement, permission isolation, and cost control creates a continuing engineering market.</p><h3 id="_5-ongoing-operations" tabindex="-1">5. Ongoing operations <a class="header-anchor" href="#_5-ongoing-operations" aria-label="Permalink to &quot;5. Ongoing operations&quot;">​</a></h3><p>Model upgrades, prompt and knowledge updates, monitoring, failure recovery, cost analysis, and repeated evaluation continue after delivery. Revenue may evolve toward a combination of implementation fees, annual operations, usage charges, and ongoing optimization.</p><h3 id="_6-security-governance-and-audit" tabindex="-1">6. Security governance and audit <a class="header-anchor" href="#_6-security-governance-and-audit" aria-label="Permalink to &quot;6. Security governance and audit&quot;">​</a></h3><p>The document includes security governance among its service categories and calls for cybersecurity, data security, ethics, and business compliance throughout the process. Authorization controls, tool admission, operating records, content traceability, risk warnings, independent evaluation, and incident recovery may support distinct products and services.</p><h3 id="_7-testing-and-evaluation" tabindex="-1">7. Testing and evaluation <a class="header-anchor" href="#_7-testing-and-evaluation" aria-label="Permalink to &quot;7. Testing and evaluation&quot;">​</a></h3><p>Provider maturity, model capability, agent reliability, application outcomes, and security risk all require assessment. Third-party testing intended to carry evidentiary weight may trigger applicable CMA/CNAS qualification requirements; ordinary product self-testing must not be presented as statutory or authoritative third-party assessment.</p><h3 id="_8-fde-training-and-field-services" tabindex="-1">8. FDE training and field services <a class="header-anchor" href="#_8-fde-training-and-field-services" aria-label="Permalink to &quot;8. FDE training and field services&quot;">​</a></h3><p>Universities, vocational institutions, leading providers, and training organizations can develop FDE courses, practical training, certification, and talent services. Enterprises may establish resident, regionally shared, or combined remote-and-onsite teams.</p><h3 id="_9-consortium-membership-and-foundational-capabilities" tabindex="-1">9. Consortium membership and foundational capabilities <a class="header-anchor" href="#_9-consortium-membership-and-foundational-capabilities" aria-label="Permalink to &quot;9. Consortium membership and foundational capabilities&quot;">​</a></h3><p>Not every enterprise needs to be a prime contractor. Computing, data, model, terminal, security, protocol, runtime, and development-tool companies can join delivery projects through consortium membership.</p><h3 id="_10-overseas-applications" tabindex="-1">10. Overseas applications <a class="header-anchor" href="#_10-overseas-applications" aria-label="Permalink to &quot;10. Overseas applications&quot;">​</a></h3><p>The notice refers to overseas projects through Belt and Road, BRICS, and China–ASEAN cooperation. Teams that combine local deployment, multilingual support, regional compliance, ongoing operations, and training may find new opportunities. The offering is an application capability, not only a software license.</p><h2 id="connections-with-existing-policies-clarify-where-demand-may-come-from" tabindex="-1">Connections with existing policies clarify where demand may come from <a class="header-anchor" href="#connections-with-existing-policies-clarify-where-demand-may-come-from" aria-label="Permalink to &quot;Connections with existing policies clarify where demand may come from&quot;">​</a></h2><p>Document No. 414 is not isolated. “AI Plus” entered the Government Work Report in 2024. In 2025, State Council Document No. 11 set targets for next-generation intelligent terminals and agent adoption above 70% by 2027 and above 90% by 2030, while promoting application service providers, Model as a Service, and Agent as a Service. <a href="https://www.smartcity.team/news/chinagovaiplan/" target="_blank" rel="noreferrer">Reprint and explanation of the State Council&#39;s AI Plus initiative</a></p><p>The 2026 Government Work Report further called for faster agent adoption, commercial and scaled AI applications in key industries, AI-native businesses, large intelligent computing clusters, computing–power coordination, and improved AI governance. <a href="https://www.moj.gov.cn/pub/sfbgw/zwgkztzl/2026nianzhuanti/2026qglh0206/lhjj20260206/lhjjyw20260206/202603/t20260313_532786.html" target="_blank" rel="noreferrer">Related content from the 2026 Government Work Report</a></p><p>Another policy stream concerns SME digital transformation. Two rounds have supported 66 cities and more than 30,000 enterprises, with plans for around 100 cities and over 40,000 enterprises, including 10,000 specialized and innovative SMEs. A further target is cloud adoption above 40% among SMEs by 2027. <a href="https://www.hlj.gov.cn/hljzqc/c100116/202412/c00_31795008.shtml" target="_blank" rel="noreferrer">SME digital empowerment action plan</a></p><p>Together, these policies describe a sequence:</p><ol><li>Set broad goals for AI adoption across the economy and society.</li><li>Supply computing, data, models, pilot-scale testing facilities, and open-source resources.</li><li>Open local industry scenarios and organize SME transformation.</li><li>Use Document No. 414 to strengthen providers that can consult, deliver, operate, and govern.</li><li>Connect dispersed participants through pools, consortia, and standards.</li></ol><p>Potential demand therefore comes from more than central fiscal funding: government scenarios, state-owned enterprise demonstrations, local funds, enterprise digital transformation budgets, computing vouchers, first-use mechanisms, risk compensation, association-led matching, consortium projects, and overseas delivery. Government helps create market conditions; revenue ultimately comes from solving real needs.</p><h2 id="who-is-positioned-to-benefit-and-who-may-struggle" tabindex="-1">Who is positioned to benefit, and who may struggle? <a class="header-anchor" href="#who-is-positioned-to-benefit-and-who-may-struggle" aria-label="Permalink to &quot;Who is positioned to benefit, and who may struggle?&quot;">​</a></h2><p>The strongest opportunities are likely to favor:</p><ul><li>Small specialist providers with industry customers and at least 10 demonstrable cases.</li><li>Software companies able to standardize offerings while retaining necessary customization.</li><li>Teams capable of taking continuing responsibility for implementation, operations, and security.</li><li>Integrators with customer relationships and project management skills sufficient to lead consortia.</li><li>Neutral platforms that support multiple models, systems, and terminals.</li><li>Specialists in testing, evaluation, governance, training, or FDE services.</li><li>Teams that turn open-source technology into installable, maintainable, auditable products.</li></ul><p>Providers with demonstrations but no contractual delivery cases, thin wrappers around a single model that cannot connect to customer systems, and projects without post-launch operators or clear accountability will find it harder to earn organizational customers&#39; long-term trust.</p><h2 id="a-three-stage-outlook" tabindex="-1">A three-stage outlook <a class="header-anchor" href="#a-three-stage-outlook" aria-label="Permalink to &quot;A three-stage outlook&quot;">​</a></h2><h3 id="stage-1-before-the-end-of-2026-visibility-and-organizational-participation" tabindex="-1">Stage 1: before the end of 2026, visibility and organizational participation <a class="header-anchor" href="#stage-1-before-the-end-of-2026-visibility-and-organizational-participation" aria-label="Permalink to &quot;Stage 1: before the end of 2026, visibility and organizational participation&quot;">​</a></h3><p>Regions must submit pool and consortium information before December 1. The first round may emphasize identification and coverage, favoring established software providers, digital transformation firms, and integrators with existing cases, local connections, and complete records.</p><p>The keyword is visibility. Smaller innovative teams should prepare their entity, team, service manuals, case evidence, and industry positioning rather than wait for the national online platform.</p><h3 id="stage-2-in-2027-competition-shifts-toward-maturity-and-demonstrated-outcomes" tabindex="-1">Stage 2: in 2027, competition shifts toward maturity and demonstrated outcomes <a class="header-anchor" href="#stage-2-in-2027-competition-shifts-toward-maturity-and-demonstrated-outcomes" aria-label="Permalink to &quot;Stage 2: in 2027, competition shifts toward maturity and demonstrated outcomes&quot;">​</a></h3><p>As the national pool target rises from more than 2,000 to no fewer than 3,000, membership alone becomes less distinctive. As general requirements, maturity assessments, and FDE capability standards develop, providers may be differentiated by capability, industry, region, and results. Local summaries will also create demand for exemplary providers, solutions, and consortia.</p><p>The keyword is verification. Reliable reuse, measurable benefits, controlled risk, and repeat customer purchases will matter more than inclusion in the first list.</p><h3 id="stage-3-from-2028-to-2030-ai-services-may-enter-routine-procurement" tabindex="-1">Stage 3: from 2028 to 2030, AI services may enter routine procurement <a class="header-anchor" href="#stage-3-from-2028-to-2030-ai-services-may-enter-routine-procurement" aria-label="Permalink to &quot;Stage 3: from 2028 to 2030, AI services may enter routine procurement&quot;">​</a></h3><p>If adoption continues toward the State Council&#39;s targets, AI services may increasingly enter ordinary organizational budgets, alongside cloud, cybersecurity, and enterprise software. Procurement may move from one-time construction toward combinations of agent seats, token consumption, operating service levels, security responsibilities, and outcome measures.</p><p>The pool could become more closely connected with local projects, state-owned enterprise procurement, industrial platforms, standards certification, credit evaluation, and cross-regional matching. This is a projection from current mechanisms: Document No. 414 does not establish such a procurement system.</p><h2 id="risks-that-remain" tabindex="-1">Risks that remain <a class="header-anchor" href="#risks-that-remain" aria-label="Permalink to &quot;Risks that remain&quot;">​</a></h2><p>First, early pools may prioritize quantity over quality. Pressure to meet the 2,000- and 3,000-provider targets may produce uneven lists, requiring later maturity standards and dynamic evaluation.</p><p>Second, case thresholds may disadvantage genuinely young teams. The expectation of at least 10 cases for providers with under three years of experience may favor established integrators with customer channels over technically innovative startups.</p><p>Third, consortia may become nominal partnerships. Member lists cannot solve complex delivery problems without clear technical boundaries, delivery responsibilities, data permissions, and incident accountability.</p><p>Fourth, project-based revenue may bring low margins and long collection cycles. Government-organized demand does not automatically give providers pricing power. Custom development can still become highly price-competitive.</p><p>Fifth, security governance may be reduced to certificate checking. Agent security also depends on authorization for each invocation, observable facts, failure states, independent acceptance, and recovery from side effects. Governance must reach the operating process to support long-term responsibility.</p><h2 id="conclusion-building-the-delivery-layer-that-takes-ai-into-industry" tabindex="-1">Conclusion: building the delivery layer that takes AI into industry <a class="header-anchor" href="#conclusion-building-the-delivery-layer-that-takes-ai-into-industry" aria-label="Permalink to &quot;Conclusion: building the delivery layer that takes AI into industry&quot;">​</a></h2><p>The central significance of Document No. 414 is not an announcement of another 3,000 companies carrying an AI label. It is a systematic policy answer to a practical question: once models and computing resources exist, who will take them into industries and enterprises?</p><p>The answer is not one model vendor or one employee who knows how to write prompts. It is a service workforce able to understand industries, combine technologies, work in real settings, sustain operations, and carry security responsibility.</p><p>Provider profiles, national pools, consortia, real scenarios, first-use mechanisms, risk compensation, computing vouchers, FDEs, customer evidence, and local evaluation form a connected policy mechanism. Government is seeking to accelerate the formation of a dispersed market by reducing information costs, initial procurement risk, and access costs for foundational resources.</p><p>For entrepreneurs, the opportunity is to become capable of real delivery. For software firms, it is to make frequent business needs into reusable products.</p><p>As the industry moves from asking whose model is stronger to asking who can keep AI working over time, the deeper competition is only beginning.</p><h2 id="sources-and-scope" tabindex="-1">Sources and scope <a class="header-anchor" href="#sources-and-scope" aria-label="Permalink to &quot;Sources and scope&quot;">​</a></h2><ul><li><a href="https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_331b6f1d28ad410aa9df711acf42dbfe.html" target="_blank" rel="noreferrer">MIIT Document No. 414 and its five annexes</a></li><li><a href="https://www.ordoszxqy.org.cn/policy/info/6015" target="_blank" rel="noreferrer">Reprint of MIIT&#39;s seven-question policy explanation</a></li><li><a href="https://www.smartcity.team/news/chinagovaiplan/" target="_blank" rel="noreferrer">Reprint and explanation of the State Council&#39;s AI Plus policy</a></li><li><a href="https://www.moj.gov.cn/pub/sfbgw/zwgkztzl/2026nianzhuanti/2026qglh0206/lhjj20260206/lhjjyw20260206/202603/t20260313_532786.html" target="_blank" rel="noreferrer">2026 Government Work Report</a></li><li><a href="https://data.beijing.gov.cn/xydt/ljhd/3ec621d485334da1acb48eb907172bdd.htm" target="_blank" rel="noreferrer">National Data Administration information on average daily token usage</a></li><li><a href="https://www.hlj.gov.cn/hljzqc/c100116/202412/c00_31795008.shtml" target="_blank" rel="noreferrer">SME Digital Empowerment Action Plan, 2025–2027</a></li><li><a href="https://hai.stanford.edu/ai-index/2025-ai-index-report" target="_blank" rel="noreferrer">Stanford AI Index Report 2025</a></li></ul><p>Forward-looking statements in this article are analysis based on current policy mechanisms. They do not stand for unpublished local application rules, subsidy amounts, procurement quotas, or final national pool admission standards. Statistics from different sources use different populations and definitions: AI enterprise counts, core industry size, service provider pool counts, and organizational AI use cannot be substituted for one another. They are used here only to describe the industrial context and policy stage.</p>',175))])}const x=o(u,[["render",m]]);export{k as __pageData,x as default};
